def test_dashboard_projects_only_valid_simulated_rotation_facts(
    tmp_path: Path,
) -> None:
    from open_trader.dashboard import _project_simulated_rotation_pairs
    from open_trader.trend_review import _rotation_pair_key

    report_sha = "a" * 64
    common = {
        "schema_version": "open_trader.trend_review.rotation.v1",
        "market": "US",
        "account_id": 101,
        "execution_date": "2026-07-20",
        "report_sha256": report_sha,
    }

    def root(pair_index: int) -> tuple[Path, str]:
        pair_key = _rotation_pair_key(
            "US", 101, "2026-07-20", report_sha, pair_index
        )
        path = (
            tmp_path / "trend_review/ledgers/US/rotations/2026-07-20"
            / pair_key
        )
        path.mkdir(parents=True)
        return path, pair_key

    terminal_root, terminal_key = root(0)
    (terminal_root / "terminal.json").write_text(json.dumps({
        **common, "kind": "terminal", "pair_index": 0,
        "pair_key": terminal_key, "status": "complete",
    }), encoding="utf-8")

    fill_root, fill_key = root(1)
    request = {
        "market": "US", "futu_code": "US.WEAK", "side": "SELL",
        "qty": "10", "remark": "rotation:test",
    }
    (fill_root / "sell-filled.json").write_text(json.dumps({
        **common, "kind": "sell_fill", "status": "filled",
        "pair_index": 1, "pair_key": fill_key,
        "sell_futu_symbol": "US.WEAK", "buy_futu_symbol": "US.STRONG",
        "target_qty": "10", "filled_qty": "10", "request": request,
        "order": {
            "order_id": "sell-1", "code": "US.WEAK", "trd_side": "SELL",
            "remark": "rotation:test", "qty": "10", "dealt_qty": "10",
            "order_status": "FILLED_ALL",
        },
    }), encoding="utf-8")

    invalid_root, _ = root(2)
    (invalid_root / "terminal.json").write_text("{broken", encoding="utf-8")
    unrelated_key = _rotation_pair_key(
        "US", 202, "2026-07-20", report_sha, 2
    )
    (invalid_root / "unrelated.json").write_text(json.dumps({
        **common, "account_id": 202, "kind": "terminal", "pair_index": 2,
        "pair_key": unrelated_key, "status": "complete",
    }), encoding="utf-8")

    frozen_pairs = [{"pair_index": index} for index in range(3)]
    projected = _project_simulated_rotation_pairs(
        frozen_pairs,
        data_dir=tmp_path,
        market="US",
        execution_date="2026-07-20",
        report_sha256=report_sha,
        account_id=101,
    )

    assert [pair["execution_status"] for pair in projected] == [
        "完成", "卖出已成交", "待执行",
    ]
    assert frozen_pairs == [{"pair_index": index} for index in range(3)]


def test_dashboard_v2_keeps_latest_report_plans_when_batch_is_older(
    tmp_path: Path,
) -> None:
    from open_trader.dashboard import _project_broker_trend_report
    from open_trader.trend_review import _report_hash

    data_dir = tmp_path / "data"
    reports_root = tmp_path / "reports"
    reports_dir = reports_root / "trend_us_futu"
    older = write_trend_history_report(
        reports_root,
        "2026-08-19.json",
        execution_date="2026-08-20",
        generated_at="2026-08-19T20:00:00+08:00",
    )
    older_path = reports_dir / "2026-08-19.json"
    batch_path = data_dir / "trend_review/ledgers/US/batches/2026-08-20.json"
    batch_path.parent.mkdir(parents=True)
    batch_path.write_text(json.dumps({
        "schema_version": "open_trader.trend_review.batch.v1",
        "market": "US",
        "execution_date": "2026-08-20",
        "report_path": str(older_path),
        "report_sha256": _report_hash(older),
        "locked_at": "2026-08-20T09:30:00-04:00",
    }), encoding="utf-8")
    latest = _v2_dashboard_plan_payload()
    selected = (
        reports_dir / "2026-08-20-r1.json",
        latest,
        date(2026, 8, 20),
        date(2026, 8, 19),
        date(2026, 8, 20),
        datetime(2026, 8, 20, 20, tzinfo=timezone(timedelta(hours=8))),
    )

    projected = _project_broker_trend_report(
        selected=selected,
        data_dir=data_dir,
        reports_dir=reports_dir,
        broker="futu",
        market="US",
        market_label="美股",
        broker_label="富途",
        buy_window="美股常规交易时段",
        report_date="2026-08-21",
        use_execution_batch=True,
    )

    assert projected["available"] is True
    assert projected["artifact"] == "2026-08-20-r1.json"
    assert projected["buy_actions"][0]["symbol"] == "LATEST"
    assert projected["execution_batch"]["report_sha256"] == _report_hash(older)
    assert projected["latest_report_sha256"] == _report_hash(latest)
    assert projected["revision_anomaly"] is True


def test_dashboard_v2_keeps_plans_when_execution_batch_is_invalid(
    tmp_path: Path,
) -> None:
    from open_trader.dashboard import _project_broker_trend_report
    from open_trader.trend_review import _report_hash

    latest = _v2_dashboard_plan_payload()
    data_dir = tmp_path / "data"
    reports_dir = tmp_path / "reports" / "trend_us_futu"
    batch_path = data_dir / "trend_review/ledgers/US/batches/2026-08-20.json"
    batch_path.parent.mkdir(parents=True)
    batch_path.write_text("{broken", encoding="utf-8")

    projected = _project_broker_trend_report(
        selected=(
            reports_dir / "2026-08-20.json",
            latest,
            date(2026, 8, 20),
            date(2026, 8, 19),
            date(2026, 8, 20),
            datetime(2026, 8, 20, 20, tzinfo=timezone(timedelta(hours=8))),
        ),
        data_dir=data_dir,
        reports_dir=reports_dir,
        broker="futu",
        market="US",
        market_label="美股",
        broker_label="富途",
        buy_window="美股常规交易时段",
        report_date="2026-08-21",
        use_execution_batch=True,
    )

    assert projected["available"] is True
    assert projected["artifact"] == "2026-08-20.json"
    assert projected["report_sha256"] == _report_hash(latest)
    assert projected["buy_actions"][0]["symbol"] == "LATEST"
