    assert projected["simulate_rotation_pairs"] == payload["strategy_judgments"][
        "simulate_rotation_pairs"
    ]
    assert projected["real_rotation_pairs"] == payload["strategy_judgments"][
        "real_rotation_pairs"
    ]


