def test_lp_failed_candidate_hidden_with_diagnostics() -> None:
    output = run_dashboard_js(r'''
Date.now = () => Date.parse("2026-09-20T03:00:10Z");
const checkedAt = "2026-09-20T03:00:00Z";
const selected = {
  outcome: "YES", price: "0.23", quantity: "50", required_capital: "11.50",
  estimated_exit_loss: "1.15", estimated_exit_loss_ratio: "0.10", checked_at: checkedAt,
};
const validRunner = {
  market_id: "market-runner", condition_id: "condition-runner",
  market_title: "Valid runner", market_url: "https://polymarket.com/event/runner",
  outcome: "NO", state: "eligible", realtime_checked_at: checkedAt,
  selected_direction: selected,
  competition: {state: "known", value: "2", checked_at: checkedAt},
  reason: ["保留的检查时快照"], summary: {},
};
const failedHead = (state, conditionId, reasonCodes) => ({
  market_id: "market-" + conditionId, condition_id: conditionId,
  market_title: "Failed head", market_url: "https://polymarket.com/event/" + conditionId,
  outcome: "NO", state, realtime_checked_at: checkedAt, selected_direction: null,
  updated_at: checkedAt, expires_at: "2026-09-20T03:05:00Z",
  refresh_failed: true,
  directions: {
    YES: {state, eligible: false, reason_codes: reasonCodes},
    NO: {state, eligible: false, reason_codes: reasonCodes},
  },
});
const noPlan = {
  ...validRunner, market_id: "market-no-plan", condition_id: "condition-no-plan",
  market_title: "Claimed eligible without plan", outcome: "NO", state: "eligible",
  selected_direction: null,
};
const base = {
  state: "ready", complete: true, scanning: false, checked_at: checkedAt,
  candidate_state: "ready", candidate_stale: false,
  candidate_checked_at: checkedAt, candidate_last_success_at: checkedAt,
  orders: [], positions: [], lp_orders_today: [], market_rewards: {},
  lp_observations: {}, lp_share_watch_state: {}, non_lp_row_count: 0,
  funnel: {
    normal_queue_count: 2, backup_queue_count: 0, checked: 2, passed: 1,
    rejected: 1, unknown: 0, unchecked: 0, stop_reason: "queue_exhausted",
    excluded: {}, compared_range: {compared: 2, total: 2, pending: 0},
    budget: {available_capital: "50.00"},
  },
};
const render = (head, candidates = [head, validRunner]) => predictionLpCard({
  lp_dashboard: {...base, candidates, recommendations: [], selected_results: [head, validRunner]},
});
const table = (html) => {
  const start = html.indexOf("pm-lp-candidate-table");
  return html.slice(start, html.indexOf("</table>", start));
};
const unknownHtml = render(failedHead(
  "unknown", "condition-failed-unknown", ["account_freshness_stale", "market_metadata_stale"],
));
const rejectedHtml = render(failedHead(
  "rejected", "condition-failed-rejected", ["market_metadata_stale"],
));
const noPlanHtml = render(noPlan, [noPlan, validRunner]);
console.log(JSON.stringify({
  unknownVisibleDegraded: table(unknownHtml).includes("condition-failed-unknown")
    && table(unknownHtml).includes("刷新失败 · 保留至原到期"),
  unknownReasonVisible: unknownHtml.includes("account_freshness_stale")
    && unknownHtml.includes("market_metadata_stale"),
  unknownRunnerKept: table(unknownHtml).includes("condition-runner"),
  unknownRunnerNotCurrent: !table(unknownHtml).includes("当前推荐"),
  rejectedVisibleDegraded: table(rejectedHtml).includes("condition-failed-rejected")
    && table(rejectedHtml).includes("刷新失败 · 保留至原到期"),
  rejectedReasonVisible: rejectedHtml.includes("market_metadata_stale"),
  rejectedRunnerKept: table(rejectedHtml).includes("condition-runner"),
  noPlanHidden: !table(noPlanHtml).includes("condition-no-plan")
    && !table(noPlanHtml).includes("买 NO"),
  noPlanRunnerKept: table(noPlanHtml).includes("condition-runner"),
}));
''')
    rendered = json.loads(output)
    assert rendered == {
        "unknownVisibleDegraded": True,
        "unknownReasonVisible": True,
        "unknownRunnerKept": True,
        "unknownRunnerNotCurrent": True,
        "rejectedVisibleDegraded": True,
        "rejectedReasonVisible": True,
        "rejectedRunnerKept": True,
        "noPlanHidden": True,
        "noPlanRunnerKept": True,
    }, rendered


def test_lp_render_fidelity_and_monotonic_fetch() -> None:
    """S5: 重渲染按 data-key 恢复展开与滚动锚点；旧响应不得覆盖新响应。"""
    output = run_dashboard_js(r"""
const result = {};

// --- details/scroll fidelity ---
const detailStubs = {
  "lp-candidate-evidence-condition-a": {key: "lp-candidate-evidence-condition-a", open: false},
  "lp-candidate-evidence-condition-b": {key: "lp-candidate-evidence-condition-b", open: true},
};
const fakeRoot = {
  querySelectorAll(selector) {
    if (selector.includes("[open]")) {
      return Object.values(detailStubs).filter((el) => el.open)
        .map((el) => ({getAttribute: () => el.key}));
    }
    return Object.values(detailStubs)
      .map((el) => ({getAttribute: () => el.key, set open(value) { el.open = value; }, get open() { return el.open; }}));
  },
};
globalThis.window = {
  location: {search: ""},
  scrollY: 1200,
  scrollTo(x, y) { result.scrolledTo = y; },
  setInterval() { return 1; },
  clearInterval() {},
};
const snapshot = lpRenderFidelitySnapshot(fakeRoot);
result.capturedKeys = [...snapshot.open];
result.capturedAnchor = snapshot.anchor;
detailStubs["lp-candidate-evidence-condition-b"].open = false;
lpRenderFidelityRestore(fakeRoot, snapshot);
result.restoredA = detailStubs["lp-candidate-evidence-condition-a"].open;
result.stillB = detailStubs["lp-candidate-evidence-condition-b"].open;
result.scrolledTo;

// --- monotonic fetch: an older response must never overwrite a newer read ---
state.workspaceView = "prediction_market";
state.predictionMarket.activeTab = "lp";
state.predictionMarket.csrfToken = "csrf-token";
const response = (data, ok = true, status = 200) => ({ok, status, json: async () => data});
let resolveFirst;
let fetchCount = 0;
globalThis.fetch = async (url) => {
  fetchCount += 1;
  if (String(url).endsWith("/api/prediction-arbitrage/lp/dashboard") && fetchCount === 1) {
    return new Promise((resolve) => { resolveFirst = resolve; });
  }
  if (String(url).endsWith("/api/prediction-arbitrage/venues")) return response({csrf_token:"t", n_leg:{status:"running"}, venues: [], monitor_subscription: {}});
  return response({
    state: "ready", stale: false, complete: true,
    checked_at: "2026-09-19T03:00:00Z",
    lp_session: {state: "none"}, orders: [], positions: [], lp_orders_today: [],
    market_rewards: {}, lp_share_watch_state: {}, non_lp_row_count: 0,
    recommendations: [],
    candidates: [{market_id: "market-new", condition_id: "condition-new", market_title: "Newer candidate", min_quantity: "20", competition: {state: "unknown"}}],
    funnel: {read: 1, base: 1, sort: 1, trial: 1, excluded: {}, compared_range: {}, budget: {}},
  });
};
const firstRequest = fetchPredictionLpDashboard();
// A newer request supersedes the in-flight one (seq bumped like a new call does).
state.predictionMarket.lpDashboardRequestSeq += 1;
resolveFirst(response({
  state: "ready", stale: false, complete: true,
  checked_at: "2026-09-19T01:00:00Z",
  lp_session: {state: "none"}, orders: [], positions: [], lp_orders_today: [],
  market_rewards: {}, lp_share_watch_state: {}, non_lp_row_count: 0,
  recommendations: [],
  candidates: [{market_id: "market-old", condition_id: "condition-old", market_title: "Stale candidate", min_quantity: "20", competition: {state: "unknown"}}],
  funnel: {read: 1, base: 1, sort: 1, trial: 1, excluded: {}, compared_range: {}, budget: {}},
}));
await firstRequest;
result.staleDiscarded = state.predictionMarket.lpDashboard?.candidates?.[0]?.market_title !== "Stale candidate";
const second = fetchPredictionLpDashboard();
await second;
result.newerApplied = state.predictionMarket.lpDashboard?.candidates?.[0]?.market_title === "Newer candidate";
console.log(JSON.stringify(result));
""")
    rendered = json.loads(output)
    assert rendered == {
        "capturedKeys": ["lp-candidate-evidence-condition-b"],
        "capturedAnchor": 1200,
        "restoredA": False,
        "stillB": True,
        "scrolledTo": 1200,
        "staleDiscarded": True,
        "newerApplied": True,
    }


def _lp_cancel_render_dashboard() -> str:
    return r"""
const checkedAt = "2026-09-20T02:00:00Z";
const order = (orderId, conditionId, title, price, quantity, extra) => ({
  order_id: orderId, condition_id: conditionId,
  token_id: "token-" + orderId,
  market_title: title, market_url: "https://polymarket.com/event/" + conditionId,
  outcome: "YES", side: "BUY", status: "LIVE", price,
  quantity, filled_quantity: "0", remaining_quantity: quantity,
  state: "open", purpose: "formal",
  management: "manual_read_only", read_only: true,
  scoring_status: "true", scoring_checked_at: checkedAt,
  ...(extra || {}),
});
const dashboard = {
  state: "ready", stale: false, checked_at: checkedAt, last_success_at: checkedAt,
  orders: [], positions: [],
  lp_orders_today: [
    order("a1", "condition-a", "Market A", "0.23", "650"),
    order("a2", "condition-a", "Market A", "0.23", "300"),
    order("b1", "condition-b", "Market B", "0.31", "120"),
    order("c1", "condition-c", "Market C", "0.45", "60",
      {status: "MATCHED", state: "filled", filled_quantity: "60",
       remaining_quantity: "0", last_fill_at: checkedAt, purpose: null}),
  ],
  non_lp_row_count: 0, market_rewards: {}, reward_shares: {},
  lp_observations: {}, recommendations: [], lp_session: {state: "none"},
};
const html = predictionLpCard({lp_dashboard: dashboard});
const orderTable = (html.match(/<table class="pm-table pm-lp-order-table">[\s\S]*?<\/table>/) || [""])[0];
const rowSegments = orderTable.split("<tr data-lp-today-market=").slice(1);
const rowFor = (conditionId) => rowSegments.find(
  (segment) => segment.startsWith("\"" + conditionId + "\"")) || "";
const marketARow = rowFor("condition-a");
const marketBRow = rowFor("condition-b");
const marketCRow = rowFor("condition-c");
"""


def test_lp_cancel_buttons_render_enabled_per_order_and_market_targets() -> None:
    """D1/D2/D3: 可撤单行渲染启用的逐笔与组级撤单按钮(带目标、无 disabled、
    无预留位提示);已成交行不渲染撤单按钮。"""
    output = run_dashboard_js(_lp_cancel_render_dashboard() + r"""
console.log(JSON.stringify({
  perOrderA1: marketARow.includes(
    'data-action="lp-cancel-order" data-order-id="a1"'),
  perOrderA2: marketARow.includes(
    'data-action="lp-cancel-order" data-order-id="a2"'),
  marketButtonA: marketARow.includes(
    'data-action="lp-cancel-market" data-condition-id="condition-a"'),
  noDisabledButtons: !/<button[^>]*lp-cancel[^>]*disabled/.test(orderTable),
  noPlaceholderTitle: !orderTable.includes("预留位"),
  singleOrderB1: marketBRow.includes(
    'data-action="lp-cancel-order" data-order-id="b1"'),
  filledRowNoCancel: !marketCRow.includes("lp-cancel"),
}));
""")
    rendered = json.loads(output)

    assert rendered == {
        "perOrderA1": True,
        "perOrderA2": True,
        "marketButtonA": True,
        "noDisabledButtons": True,
        "noPlaceholderTitle": True,
        "singleOrderB1": True,
        "filledRowNoCancel": True,
    }


